//! Symbols generated by theorem declarations and their counter dependencies.
use crate::{
    syntax::{self, Argument, Command},
    workspace::{Document, Workspace},
};
use std::{collections::BTreeSet, ops::Range};
use tower_lsp::{
    jsonrpc::{Error, Result},
    lsp_types::Url,
};

#[derive(Clone, Copy)]
pub(crate) struct Theorem {
    numbered: bool,
    owns_counter: bool,
}

struct Declaration<'a> {
    name: &'a str,
    theorem: Theorem,
    shared: Option<Argument>,
    within: Option<Argument>,
}

fn declaration<'a>(doc: &'a Document, command: &Command) -> Option<Declaration<'a>> {
    if command.name != "newtheorem" {
        return None;
    }
    let argument = command.argument.as_ref()?;
    let name = doc.text.source[argument.span.clone()].trim();
    let source = &doc.text.source;
    let numbered = !source[command.span.end..argument.outer_span.start]
        .trim_start()
        .starts_with('*');
    let after = syntax::skip_space(source, argument.outer_span.end);
    let shared = syntax::group(source, after, b'[', b']');
    let title_start = shared
        .as_ref()
        .map_or(after, |(_, end)| syntax::skip_space(source, *end));
    let title = syntax::group(source, title_start, b'{', b'}');
    let within = if shared.is_none() {
        title
            .and_then(|(_, end)| syntax::group(source, syntax::skip_space(source, end), b'[', b']'))
            .map(|(argument, _)| argument)
    } else {
        None
    };
    Some(Declaration {
        name,
        theorem: Theorem {
            numbered,
            owns_counter: numbered && shared.is_none(),
        },
        shared: shared.map(|(argument, _)| argument),
        within,
    })
}

pub(crate) fn in_scope(
    workspace: &Workspace,
    scope: &BTreeSet<Url>,
    name: &str,
) -> Option<Theorem> {
    workspace
        .documents
        .iter()
        .filter(|(uri, _)| scope.contains(*uri))
        .find_map(|(_, doc)| {
            doc.syntax
                .commands
                .iter()
                .filter_map(|command| declaration(doc, command))
                .find(|declaration| declaration.name == name)
                .map(|declaration| declaration.theorem)
        })
}

fn generated_names(name: &str, theorem: Theorem) -> Vec<(String, usize)> {
    let mut names = vec![(name.into(), 0), (format!("end{name}"), 3)];
    if theorem.numbered {
        names.push((format!("the{name}"), 3));
    }
    if theorem.owns_counter {
        for prefix in ["theH", "c@", "cl@", "p@"] {
            names.push((format!("{prefix}{name}"), prefix.len()));
        }
        names.push((format!("{name}autorefname"), 0));
    }
    names
}

pub(crate) struct Reference {
    pub span: Range<usize>,
    selection_span: Range<usize>,
    control_word: bool,
}

pub(crate) fn references(doc: &Document, name: &str, theorem: Theorem) -> Vec<Reference> {
    let mut result = Vec::new();
    let generated = generated_names(name, theorem);
    for (index, command) in doc.syntax.commands.iter().enumerate() {
        if let Some((_, prefix)) = generated
            .iter()
            .find(|(generated, _)| generated == &command.name)
        {
            let start = command.span.start + 1 + prefix;
            result.push(Reference {
                span: start..start + name.len(),
                selection_span: command.span.clone(),
                control_word: true,
            });
        }
        if command.name == "csname" {
            if let Some(end) = doc
                .syntax
                .commands
                .get(index + 1)
                .filter(|command| command.name == "endcsname")
            {
                let span = syntax::trimmed_span(&doc.text.source, command.span.end..end.span.start);
                if let Some((_, prefix)) = generated
                    .iter()
                    .find(|(name, _)| *name == doc.text.source[span.clone()])
                {
                    let start = span.start + prefix;
                    result.push(Reference {
                        span: start..start + name.len(),
                        selection_span: span,
                        control_word: false,
                    });
                }
            }
        }
        let mut arguments = Vec::new();
        if matches!(command.name.as_str(), "crefname" | "Crefname") {
            arguments.extend(command.argument.iter().cloned());
        }
        if theorem.owns_counter {
            let counter = matches!(
                command.name.as_str(),
                "setcounter"
                    | "addtocounter"
                    | "stepcounter"
                    | "refstepcounter"
                    | "usecounter"
                    | "value"
                    | "arabic"
                    | "roman"
                    | "Roman"
                    | "alph"
                    | "Alph"
                    | "fnsymbol"
            );
            let pair = matches!(
                command.name.as_str(),
                "counterwithin"
                    | "counterwithout"
                    | "numberwithin"
                    | "@addtoreset"
                    | "@removefromreset"
            );
            if counter || pair {
                arguments.extend(command.argument.iter().cloned());
            }
            if pair {
                if let Some(first) = &command.argument {
                    arguments.extend(
                        syntax::group(
                            &doc.text.source,
                            syntax::skip_space(&doc.text.source, first.outer_span.end),
                            b'{',
                            b'}',
                        )
                        .map(|(argument, _)| argument),
                    );
                }
            }
            if let Some(declaration) = declaration(doc, command) {
                arguments.extend(declaration.shared);
                arguments.extend(declaration.within);
            }
            if command.name == "newcounter" {
                if let Some(first) = &command.argument {
                    arguments.extend(
                        syntax::group(
                            &doc.text.source,
                            syntax::skip_space(&doc.text.source, first.outer_span.end),
                            b'[',
                            b']',
                        )
                        .map(|(argument, _)| argument),
                    );
                }
            }
            if command.name == "newaliascnt" {
                if let Some(first) = &command.argument {
                    arguments.extend(
                        syntax::group(
                            &doc.text.source,
                            syntax::skip_space(&doc.text.source, first.outer_span.end),
                            b'{',
                            b'}',
                        )
                        .map(|(argument, _)| argument),
                    );
                }
            }
        }
        result.extend(
            arguments
                .into_iter()
                .filter(|argument| argument.value.trim() == name)
                .map(|argument| {
                    let span = syntax::trimmed_span(&doc.text.source, argument.span);
                    Reference {
                        span: span.clone(),
                        selection_span: span,
                        control_word: false,
                    }
                }),
        );
    }
    result
}

pub(crate) fn target<'a>(
    workspace: &'a Workspace,
    scope: &BTreeSet<Url>,
    doc: &Document,
    offset: usize,
) -> Option<(&'a str, Range<usize>)> {
    let mut target = None;
    for (uri, definition) in &workspace.documents {
        if !scope.contains(uri) {
            continue;
        }
        for declaration in definition
            .syntax
            .commands
            .iter()
            .filter_map(|command| declaration(definition, command))
        {
            if let Some(reference) = references(doc, declaration.name, declaration.theorem)
                .into_iter()
                .find(|reference| {
                    reference.selection_span.start <= offset
                        && offset <= reference.selection_span.end
                })
            {
                if target
                    .as_ref()
                    .is_some_and(|(name, _)| *name != declaration.name)
                {
                    return None;
                }
                target = Some((declaration.name, reference.span));
            }
        }
    }
    target
}

pub(crate) fn validate(
    workspace: &Workspace,
    scope: &BTreeSet<Url>,
    old: &str,
    new: &str,
    theorem: Theorem,
) -> Result<()> {
    if !syntax::is_static_key(old) {
        return Err(Error::invalid_params(
            "Theorem renames require a static environment name",
        ));
    }
    const BUILTIN_COUNTERS: &[&str] = &[
        "page",
        "part",
        "chapter",
        "section",
        "subsection",
        "subsubsection",
        "paragraph",
        "subparagraph",
        "equation",
        "figure",
        "table",
        "footnote",
        "mpfootnote",
        "enumi",
        "enumii",
        "enumiii",
        "enumiv",
        "secnumdepth",
        "tocdepth",
    ];
    if theorem.numbered && BUILTIN_COUNTERS.contains(&new) {
        return Err(Error::invalid_params(format!(
            "The counter `{new}` is already defined"
        )));
    }
    let generated = generated_names(new, theorem);
    for (uri, doc) in &workspace.documents {
        if !scope.contains(uri) {
            continue;
        }
        let counter_conflict = theorem.numbered
            && doc.syntax.commands.iter().any(|command| {
                matches!(command.name.as_str(), "newcounter" | "newaliascnt")
                    && command
                        .argument
                        .as_ref()
                        .is_some_and(|argument| argument.value.trim() == new)
            });
        let macro_conflict = generated.iter().any(|(name, _)| {
            doc.syntax
                .definitions
                .iter()
                .any(|entry| entry.name == *name)
                || doc
                    .syntax
                    .environments
                    .iter()
                    .any(|entry| entry.name == *name || format!("end{}", entry.name) == *name)
        });
        if counter_conflict || macro_conflict {
            return Err(Error::invalid_params(format!(
                "The name `{new}` conflicts with a theorem counter or generated command"
            )));
        }
        if !new
            .bytes()
            .all(|byte| byte.is_ascii_alphabetic() || byte == b'@')
            && references(doc, old, theorem)
                .iter()
                .any(|reference| reference.control_word)
        {
            return Err(Error::invalid_params(
                "Theorem names used in generated commands must contain only TeX command letters",
            ));
        }
    }
    Ok(())
}
